import ajvModule from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface ValidationIssue {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: Record<string, unknown>;
}

interface SchemaValidator {
  (input: unknown): boolean | PromiseLike<unknown>;
  errors?: ReadonlyArray<ValidationIssue> | null;
}

interface ValidatorCompiler {
  compile(schema: Record<string, unknown>): SchemaValidator;
}

type ValidatorConstructor = new (options: Record<string, unknown>) => ValidatorCompiler;

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  compiledValidator?: SchemaValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = createValidatorCompiler();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, SchemaValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const compiledValidator =
      typeof definition === 'function' ? undefined : this.compileSchema(resolved.name, definition.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, compiledValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input per specs/hal-engine-tool-input-validation/spec.md; throws only on unknown tool. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = tool.compiledValidator ?? this.validatorForSource(name, tool.definitionSource);
    if (validator(input) !== true) {
      const issues = describeValidationIssues(validator.errors ?? []);
      log.warn('tool', 'input validation failed', {name, issues});
      return {result: `Invalid input for tool "${name}": ${issues.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorForSource(toolName: string, source: ToolDefinitionSource): SchemaValidator {
    const schema = this.resolveDefinition(source).inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const compiled = this.compileSchema(toolName, schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }

  private compileSchema(toolName: string, schema: Record<string, unknown>): SchemaValidator {
    if ('$async' in schema) {
      throw new Error(`Invalid inputSchema for tool "${toolName}": unsupported schema metadata`);
    }
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
    }
  }
}

function createValidatorCompiler(): ValidatorCompiler {
  const ajvConstructor = resolveAjvConstructor(ajvModule);
  const options =
    '_addVocabularies' in ajvConstructor.prototype
      ? {allErrors: true, strict: false, validateFormats: false}
      : {allErrors: true, format: false};
  return new ajvConstructor(options);
}

function resolveAjvConstructor(mod: unknown): ValidatorConstructor {
  if (isValidatorConstructor(mod)) return mod;
  if (hasDefaultExport(mod) && isValidatorConstructor(mod.default)) return mod.default;
  throw new Error('Failed to resolve Ajv constructor');
}

function hasDefaultExport(mod: unknown): mod is {default: unknown} {
  return typeof mod === 'object' && mod !== null && 'default' in mod;
}

function isValidatorConstructor(candidate: unknown): candidate is ValidatorConstructor {
  return typeof candidate === 'function';
}

const ISSUE_FORMATTERS: Record<string, (target: string, params: Record<string, unknown>) => string> = {
  required: (target, params) => {
    const missing = String(params.missingProperty ?? '');
    const path = target ? `${target}.${missing}` : missing;
    return `missing required property "${path}"`;
  },
  type: (target, params) => `property "${target || 'input'}" must be of type ${String(params.type)}`,
  enum: (target, params) => {
    const allowedValues = params.allowedValues;
    const allowed = Array.isArray(allowedValues) ? allowedValues.map(String).join(', ') : '';
    return `property "${target || 'input'}" must be one of: ${allowed}`;
  },
};

function describeValidationIssues(issues: ReadonlyArray<ValidationIssue>): string[] {
  if (issues.length === 0) return ['schema validation failed'];
  return issues.map(formatValidationIssue);
}

function formatValidationIssue(issue: ValidationIssue): string {
  const target = normalizeFieldPath(issue.instancePath ?? issue.dataPath ?? '');
  const formatter = ISSUE_FORMATTERS[issue.keyword];
  if (formatter) return formatter(target, issue.params);
  return `property "${target || 'input'}" failed "${issue.keyword}" validation`;
}

function normalizeFieldPath(rawPath: string): string {
  if (rawPath.startsWith('/')) {
    const segments = rawPath.slice(1).split('/');
    return segments.map(unescapePointerSegment).join('.');
  }
  if (rawPath.startsWith('.')) return rawPath.slice(1);
  return rawPath;
}

function unescapePointerSegment(segment: string): string {
  return segment.replaceAll('~1', '/').replaceAll('~0', '~');
}

